WHERE cgroups.is_active = 3 AND cgroups.group_type = 2 AND cgroups.id IN (SELECT cgroup_id FROM cgroup_companies WHERE company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId}))
AND cgroups.name LIKE CONCAT("%", #{filter.searchText}, "%")
